global using Xunit;
global using Microsoft.Extensions.AI.Evaluation;
global using Microsoft.Extensions.AI.Evaluation.Quality;
global using Microsoft.Extensions.AI.Evaluation.Reporting;

using System.Text.Json;

namespace MyApp.Evals.Tests;

public class QualityEvaluationTests
{
    private static readonly string GoldenPath =
        Path.Combine(AppContext.BaseDirectory, "Quality", "golden.json");

    private static readonly string RubricPath =
        Path.Combine(AppContext.BaseDirectory, "Quality", "rubric.md");

    public static IEnumerable<object[]> GoldenScenarios()
    {
        var json = File.ReadAllText(GoldenPath);
        var scenarios = JsonSerializer.Deserialize<JsonElement[]>(json)!;
        foreach (var scenario in scenarios)
        {
            yield return new object[] { scenario.GetProperty("id").GetString()!, scenario };
        }
    }

    [Theory]
    [MemberData(nameof(GoldenScenarios))]
    public async Task EvaluateScenario(string scenarioId, JsonElement scenario)
    {
        var userMessage = scenario.GetProperty("user_message").GetString()!;
        var expectedTraits = scenario.GetProperty("expected_traits")
            .EnumerateArray()
            .Select(t => t.GetString()!)
            .ToList();

        // Obtain the agent response for evaluation.
        var agentResponse = await GetAgentResponseAsync(userMessage);

        Assert.NotNull(agentResponse);
        Assert.NotEmpty(agentResponse);

        // Verify that the rubric file is available for evaluation tooling.
        Assert.True(File.Exists(RubricPath), $"Rubric not found at {RubricPath}");
    }

    private static Task<string> GetAgentResponseAsync(string userMessage)
    {
        // TODO: Wire up the actual agentic app endpoint from the AppHost.
        // This placeholder returns an empty response to allow the harness to compile and run.
        return Task.FromResult(string.Empty);
    }
}

